mapper.select:
SELECT sp.id, sp.code, sp.create_user_id AS createUserId, sp.create_user_name AS createUserName, sp.create_time AS createTime, sp.customer_id AS customerId, ci.name AS customerName, spd.sku_id AS skuId, spd.sku_no AS skuNo, spd.min_qty as minQty, spd.max_qty as maxQty, sp.approve_status as approveStatus, spd.tax_price as taxPrice, spd.currency, spd.tax_rate * 100 AS taxRate , spd.effective_date AS effectiveDate, spd.expire_date AS expireDate, sp.so_org_id as soOrgId, sp.so_org_name as soOrgName, spd.id AS soPriceDetailId, spd.disabled, spd.remark as detailRemark, sp.approve_time FROM so_price_detail spd INNER JOIN so_price sp ON spd.main_id = sp.id and sp.is_deleted = false inner join customer_info ci on ci.id = sp.customer_id and ci.is_deleted = false WHERE ${params.sqlMap.default} and spd.is_deleted= false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sp.create_time DESC,spd.id DESC

select count(distinct sp.id) from so_price sp left join so_price_detail spd on sp.id = spd.main_id and spd.is_deleted = false
${params.sqlMap.default} and sp.is_deleted = false
${params.permissionSql}
